import {visualHoodie} from './fixtures/visual-hoodie.js';
import test from 'node:test';import assert from 'node:assert/strict';import {newProject} from '../dist/templates.js';import {clone,bounds,point,cubic,makePath} from '../dist/core.js';import {visibleBounds} from '../dist/hit.js';import {graphIds} from '../dist/object-graph.js';import {exportSvg} from '../dist/render.js';
// Small DOM boundary doubles; this is a command/integration test, not browser QA.
class ClassList{constructor(){this.s=new Set();}add(x){this.s.add(x);}remove(x){this.s.delete(x);}contains(x){return this.s.has(x);}toggle(x,on){if(on===undefined)on=!this.s.has(x);on?this.s.add(x):this.s.delete(x);}}
class Element{constructor(id){this.id=id;this.dataset={};this.style={};this.classList=new ClassList();this.value='';this.innerHTML='';this.textContent='';this.listeners={};this.disabled=false;this.tagName='DIV';}addEventListener(n,f){this.listeners[n]=f;}setAttribute(k,v){this[k]=v;}getBoundingClientRect(){return {left:0,top:0,width:900,height:800};}showModal(){this.open=true;}close(){this.open=false;}getAttribute(k){return this[k];}focus(){}select(){}setPointerCapture(){}releasePointerCapture(){}hasPointerCapture(){return true;}closest(){return null;}click(){}querySelector(){return null;}}
const els=new Map();const get=id=>{if(!els.has(id))els.set(id,new Element(id));return els.get(id);};
const front=new Element('front');front.dataset.view='front';const back=new Element('back');back.dataset.view='back';const tabs=['resources','objects'].map(t=>{const e=new Element(t);e.dataset.tab=t;return e;});
globalThis.document={querySelector:s=>get(s.slice(1)),querySelectorAll:s=>s==='[data-view]'?[front,back]:s==='[data-tab]'?tabs:[],addEventListener(){},createElement:()=>new Element('created'),hidden:false};globalThis.window={addEventListener(){}};globalThis.innerWidth=1400;globalThis.innerHeight=900;globalThis.requestAnimationFrame=f=>f();globalThis.ResizeObserver=class{observe(){}};globalThis.localStorage={setItem(){}};
const records=new Map();globalThis.indexedDB={open(){const req={};queueMicrotask(()=>{req.result={close(){},transaction(){const t={objectStore(){return {put(p){const r={};queueMicrotask(()=>{records.set(p.id,clone(p));r.result=p.id;r.onsuccess?.();t.oncomplete?.();});return r;},get(id){const r={};queueMicrotask(()=>{r.result=records.has(id)?clone(records.get(id)):undefined;r.onsuccess?.();t.oncomplete?.();});return r;},delete(id){const r={};queueMicrotask(()=>{records.delete(id);r.onsuccess?.();t.oncomplete?.();});return r;},getAll(){const r={};queueMicrotask(()=>{r.result=[...records.values()];r.onsuccess?.();t.oncomplete?.();});return r;}}}};return t;}};req.onsuccess();});return req;}};
const app=await import('../dist/app.js');
function edgePanelDocument(){const p=newProject('blank');p.liveMirror=false;const body=makePath('Torso','M100 100L400 100L400 500L100 500Z','#fff');body.category='structure';body.role='body';const a=makePath('Torso curvo','M100 240C150 210 190 280 250 260','none'),b=makePath('Manga curva','M250 260C300 280 340 300 400 320','none');a.modifiers=[{id:'edge-seam',type:'stitch',offset:4,spacing:7,rows:1}];a.category=b.category='construction';p.views.front=[body,a,b];return {p,body,a,b};}
function edgePanelClick(p){app.pointerDown(event(coord(p)));app.pointerUp(event(coord(p)));}
function edgePanelSelectCurves(a,b){edgePanelClick(cubic(a.nodes[0],a.nodes[1],.5));edgePanelClick(cubic(b.nodes[0],b.nodes[1],.5));}
// Hand-authored hoodie contour: visually closed, authored as an open Bézier loop,
// therefore migrated as construction/path rather than a template body.
function tracedTorsoDocument(){const d=edgePanelDocument();d.p.kind='hoodie';d.body.closed=false;d.body.nodes.push({...clone(d.body.nodes[0]),nid:'loop-end',edgeId:'loop-end'});delete d.body.role;delete d.body.category;d.body.semanticType='path';return d;}
test('regression: Layers Torso open-loop selection enters edge mode through the actual command',()=>{const {p,body,a,b}=tracedTorsoDocument();app.open(p);app.selectTreeObject(body.id,{});app.action('selectPanelEdges');const s=app.editorState();assert.ok(s.panelEdgeState.selection,'selected traced Torso must resolve its surface');assert.deepEqual(s.selected,[body.id]);app.pointerMove(event(coord({x:180,y:100})));assert.match(get('draft').innerHTML,/edge-hover/);edgePanelClick({x:180,y:100});edgePanelSelectCurves(a,b);assert.ok(s.panelEdgeState.selection.choice);assert.doesNotMatch(get('panel-preview').innerHTML,/data-create-edge-panel disabled/);app.cancelPanelEdges();});
const event=(p,target={closest:()=>null},extra={})=>({clientX:p.x,clientY:p.y,target,button:0,pointerId:1,preventDefault(){},...extra});
const coord=p=>{const c=app.editorState().camera;return {x:p.x*c.z+c.x,y:p.y*c.z+c.y};};
function selectedPath(){const s=app.editorState();return s.project.views[s.view].find(o=>o.id===s.selected[0]);}
function bodyId(){return app.editorState().project.views.front.find(o=>o.role==='body').id;}
test('core V1 hoodie workflow using actual UI commands',async()=>{app.open(newProject('hoodie'));get('snap').onclick();let s=app.editorState();assert.equal(s.view,'front');back.onclick();assert.equal(app.editorState().view,'back');front.onclick();const body=bodyId();app.selectId(body,false,true);app.toolSet('node');let o=selectedPath(),n=clone(o.nodes[1]);const target={closest:sel=>sel==='[data-node]'?{dataset:{node:'1'}}:null};app.pointerDown(event(coord(point(o.matrix,n)),target));app.pointerMove(event(coord({x:n.x-25,y:n.y})));app.pointerUp(event(coord({x:n.x-25,y:n.y})));assert.equal(selectedPath().nodes[1].x,n.x-25);assert.equal(app.editorState().history.past.length,1);get('snap').onclick();
app.toolSet('select');app.selectId(body,false,true);const w=bounds(selectedPath()).w;app.setProperty('w',w+40);assert.ok(Math.abs(bounds(selectedPath()).w-w-40)<.01);
const seam=app.editorState().project.views.front.find(o=>o.name==='Costura lateral izquierda');app.selectId(seam.id,false,true);app.construction('stitch',2);assert.equal(selectedPath().rows,2);app.setProperty('offset',8);assert.equal(selectedPath().offset,8);
app.addResource('jacketZip',{x:350,y:330});assert.equal(app.editorState().selected.length,1);assert.equal(selectedPath().type,'zipper');app.setProperty('h',240);app.setProperty('zipWidth',10);assert.equal(selectedPath().zipWidth,10);
app.addResource('cordWide',{x:330,y:260});app.setProperty('stroke','#333333');assert.equal(selectedPath().type,'cord');assert.equal(app.editorState().selected.length,1);
app.addResource('cargo',{x:285,y:350});const count=app.editorState().project.views.front.length;app.mirror(true);assert.ok(app.editorState().project.views.front.length>count);
app.selectId(body,false,true);app.setProperty('fill','#9baf9c');const final=JSON.stringify(app.editorState().project.views);app.undo();app.undo();app.redo();app.redo();assert.equal(JSON.stringify(app.editorState().project.views),final);await app.save(false);assert.deepEqual(records.get(app.editorState().project.id).views,app.editorState().project.views);const saved=clone(records.get(app.editorState().project.id));app.open(saved);const svg=exportSvg(app.editorState().project,'front');assert.ok(svg.includes('#9baf9c'));assert.ok(svg.includes('stroke-dasharray'));assert.ok(!svg.includes('NaN'));});
test('multi-event drag produces a single undo action and Escape rolls back',()=>{app.open(newProject('tee'));const id=bodyId();app.selectId(id,false,true);const original=clone(selectedPath().matrix),target={closest:sel=>sel==='[data-id]'?{dataset:{id}}:null};const start={x:350,y:320};app.pointerDown(event(coord(start),target));for(let i=1;i<=20;i++)app.pointerMove(event(coord({x:350+i,y:320+i})));app.pointerUp(event(coord({x:370,y:340})));assert.equal(app.editorState().history.past.length,1);app.undo();assert.deepEqual(selectedPath().matrix,original);app.pointerDown(event(coord(start),target));app.pointerMove(event(coord({x:420,y:420})));app.keyboard({key:'Escape',target:{tagName:'SVG'},preventDefault(){}});assert.deepEqual(app.editorState().project.views.front.find(o=>o.id===id).matrix,original);});
test('keyboard duplicate, group, cut, paste, undo, redo do real document edits',()=>{app.open(newProject('tee'));app.selectId(bodyId(),false,true);const key=(key,shiftKey=false)=>app.keyboard({key,shiftKey,ctrlKey:true,target:{tagName:'SVG'},preventDefault(){}});const count=app.editorState().project.views.front.length,copyCount=graphIds(app.editorState().project.views.front,[bodyId()]).length;key('d');assert.equal(app.editorState().project.views.front.length,count+copyCount);key('g');assert.ok(selectedPath().group);key('g',true);assert.ok(!selectedPath().group);key('x');assert.equal(app.editorState().project.views.front.length,count);key('v');assert.equal(app.editorState().project.views.front.length,count+copyCount);key('z');assert.equal(app.editorState().project.views.front.length,count);key('z',true);assert.equal(app.editorState().project.views.front.length,count+copyCount);});
test('zero property values and source rotations remain correct',()=>{app.open(newProject('hoodie'));app.addResource('jacketZip');app.setProperty('rotation',30);app.setProperty('rotation',45);let s=app.editorState(),z=selectedPath(),source=s.project.views.front.find(o=>o.id===z.source);assert.ok(Math.abs(Math.atan2(source.matrix[1],source.matrix[0])*180/Math.PI-45)<.001);app.setProperty('x',0);assert.ok(Math.abs(visibleBounds(z,s.project.views.front).x)<.01);app.selectId(bodyId(),false,true);app.construction('stitch');app.setProperty('offset',0);assert.equal(selectedPath().offset,0);app.setProperty('width',0);assert.equal(selectedPath().width,0);});

test('V2 UI acceptance: rectangle → bend → rib → stitch, undo/redo and reload',async()=>{app.open(newProject('blank'));app.toolSet('rect');app.pointerDown(event(coord({x:200,y:300})));app.pointerMove(event(coord({x:450,y:340})));app.pointerUp(event(coord({x:450,y:340})));assert.equal(selectedPath().type,'path');app.action('rib');assert.equal(selectedPath().modifiers[0].type,'rib');app.action('bend');let o=selectedPath();const bend=o.modifiers.find(m=>m.type==='bend'),rib=o.modifiers.find(m=>m.type==='rib');app.setModifier(bend.id,'amount',25);app.addModifier('stitch',{rows:2});assert.equal(selectedPath().modifiers.length,3);const before=JSON.stringify(app.editorState().project.views);app.action('modRemove:'+selectedPath().modifiers.at(-1).id);assert.equal(selectedPath().modifiers.length,2);app.undo();assert.equal(JSON.stringify(app.editorState().project.views),before);app.redo();assert.equal(selectedPath().modifiers.length,2);await app.save(false);const saved=clone(records.get(app.editorState().project.id));app.open(saved);o=app.editorState().project.views.front[0];assert.equal(o.modifiers[0].type,'bend');assert.equal(o.modifiers[1].type,'rib');assert.equal(o.modifiers[0].amount,25);app.selectId(o.id,false,true);app.freeze();assert.ok(app.editorState().selected.length>1);assert.ok(app.editorState().project.views.front.every(p=>!p.modifiers?.length));app.undo();assert.equal(app.editorState().project.views.front[0].modifiers.length,2);});
test('V2 live mirror via node drag, add/delete, handles and Break Symmetry commands',()=>{app.open(newProject('hoodie'));get('snap').onclick();app.selectId(bodyId(),false,true);app.toolSet('node');let o=selectedPath(),left=clone(o.nodes[0]);const target={closest:sel=>sel==='[data-node]'?{dataset:{node:'0'}}:null};app.pointerDown(event(coord(left),target));app.pointerMove(event(coord({x:left.x-20,y:left.y-10})));app.pointerUp(event(coord({x:left.x-20,y:left.y-10})));o=selectedPath();const partner=o.nodes.find(n=>n.nid===o.symmetry.pairs[o.nodes[0].nid]);assert.equal(partner.x,700-o.nodes[0].x);assert.equal(partner.y,o.nodes[0].y);app.action('curve');assert.deepEqual(partner.in,{x:700-o.nodes[0].out.x,y:o.nodes[0].out.y});const count=o.nodes.length;app.action('addNode');assert.equal(selectedPath().nodes.length,count+2);app.action('deleteNode');assert.equal(selectedPath().nodes.length,count);app.action('breakSymmetry');assert.ok(!selectedPath().symmetry);get('snap').onclick();});
test('V2 zipper parameter fields use physical length and percent controls',async()=>{app.open(newProject('blank'));app.addResource('jacketZip');app.setProperty('pathLength',200);app.setProperty('openAmount',40);app.setProperty('sliderPercent',60);let z=selectedPath();assert.equal(z.openAmount,40);assert.equal(z.slider,.6);assert.ok(get('construction-palette').innerHTML.includes('data-construction-param="pathLength"'));app.setProperty('pathLength',400);const source=app.editorState().project.views.front.find(o=>o.id===z.source);assert.ok(Math.abs(bounds(source).h-400)<.1);const state=JSON.stringify(app.editorState().project.views);app.undo();app.redo();assert.equal(JSON.stringify(app.editorState().project.views),state);await app.save(false);app.open(clone(records.get(app.editorState().project.id)));z=app.editorState().project.views.front.find(o=>o.type==='zipper');assert.equal(z.openAmount,40);assert.equal(z.slider,.6);});
test('V2 visual bend handle produces one undo step and cancel works',()=>{app.open(newProject('blank'));app.toolSet('rect');app.pointerDown(event(coord({x:150,y:250})));app.pointerMove(event(coord({x:350,y:300})));app.pointerUp(event(coord({x:350,y:300})));app.action('bend');const o=selectedPath(),bend=o.modifiers[0],before=app.editorState().history.past.length,target={closest:sel=>sel==='[data-bend]'?{dataset:{bend:bend.id}}:null};app.pointerDown(event(coord({x:250,y:275}),target));for(let i=1;i<=12;i++)app.pointerMove(event(coord({x:250,y:275+i*2})));app.pointerUp(event(coord({x:250,y:299})));assert.equal(selectedPath().modifiers[0].amount,24);assert.equal(app.editorState().history.past.length,before+1);app.undo();assert.equal(selectedPath().modifiers[0].amount,0);app.redo();assert.equal(selectedPath().modifiers[0].amount,24);});
test('V2 Alt-drag duplicates as one operation and preserves the original',()=>{app.open(newProject('blank'));app.addResource('cargo');const ids=[...app.editorState().selected],before=app.editorState().project.views.front.length,history=app.editorState().history.past.length,id=ids[0],target={closest:sel=>sel==='[data-id]'?{dataset:{id}}:null};app.pointerDown(event(coord({x:350,y:310}),target,{altKey:true}));app.pointerMove(event(coord({x:460,y:390})));app.pointerUp(event(coord({x:460,y:390})));assert.ok(app.editorState().project.views.front.length>before);assert.equal(app.editorState().history.past.length,history+1);app.undo();assert.equal(app.editorState().project.views.front.length,before);assert.ok(ids.every(id=>app.editorState().project.views.front.some(o=>o.id===id)));});
test('V2 zero size is valid and can be restored to a nonzero size',()=>{app.open(newProject('blank'));app.addResource('waistband');app.setProperty('w',0);assert.equal(bounds(selectedPath()).w,0);app.setProperty('w',200);assert.ok(Math.abs(bounds(selectedPath()).w-200)<.001);app.setProperty('h',0);assert.equal(bounds(selectedPath()).h,0);app.setProperty('h',50);assert.ok(Math.abs(bounds(selectedPath()).h-50)<.001);});
test('V2 mirror objects remain live and break independently',()=>{app.open(newProject('blank'));app.addResource('cargo',{x:270,y:350});const leftId=app.editorState().selected.find(id=>app.editorState().project.views.front.find(o=>o.id===id)?.type==='path');app.mirrorObjects();const os=app.editorState().project.views.front,left=os.find(o=>o.id===leftId),right=os.find(o=>o.id===left.mirrorPeer);assert.ok(right);app.selectId(left.id,false,true);app.setProperty('y',280);assert.equal(bounds(left).y,bounds(right).y);app.action('breakSymmetry');assert.ok(!left.mirrorPeer&&!right.mirrorPeer);const y=bounds(right).y;app.setProperty('y',300);assert.equal(bounds(right).y,y);});
test('V2 alignment and boolean operations are undoable through UI commands',()=>{const project=newProject('blank');project.liveMirror=false;app.open(project);for(const [x,y]of [[100,100],[130,120]]){app.toolSet('rect');app.pointerDown(event(coord({x,y})));app.pointerMove(event(coord({x:x+100,y:y+50})));app.pointerUp(event(coord({x:x+100,y:y+50})));}const os=app.editorState().project.views.front;app.selectId(os[0].id,false,true);app.selectId(os[1].id,true,true);app.action('align:top');assert.equal(bounds(os[0]).y,bounds(os[1]).y);app.action('boolean:union');assert.equal(app.editorState().project.views.front.length,1);app.undo();assert.equal(app.editorState().project.views.front.length,2);});
test('V2 smooth and symmetric nodes maintain aligned Bézier handles while dragging',()=>{app.open(newProject('blank'));app.toolSet('rect');app.pointerDown(event(coord({x:200,y:200})));app.pointerMove(event(coord({x:300,y:250})));app.pointerUp(event(coord({x:300,y:250})));app.toolSet('node');const nTarget={closest:sel=>sel==='[data-node]'?{dataset:{node:'1'}}:null};app.pointerDown(event(coord({x:300,y:200}),nTarget));app.pointerUp(event(coord({x:300,y:200})));app.setProperty('nodeKind','symmetric');let o=selectedPath(),n=o.nodes[1],out=clone(n.out),hTarget={closest:sel=>sel==='[data-node]'?{dataset:{node:'1',side:'out'}}:null};app.pointerDown(event(coord(out),hTarget));app.pointerMove(event(coord({x:out.x+13,y:out.y+10})));app.pointerUp(event(coord({x:out.x+13,y:out.y+10})));n=selectedPath().nodes[1];assert.ok(Math.abs(n.in.x+n.out.x-2*n.x)<.001);assert.ok(Math.abs(n.in.y+n.out.y-2*n.y)<.001);app.setProperty('nodeKind','smooth');assert.equal(selectedPath().nodes[1].kind,'smooth');app.action('corner');assert.ok(!selectedPath().nodes[1].in&&!selectedPath().nodes[1].out);});

test('V3 command acceptance: new left cargo creates reflected instance and param changes/deletion are undoable',async()=>{app.open(newProject('pants'));app.addResource('pocket-cargoFlap',{x:270,y:360});const s=app.editorState(),left=selectedPath(),id=left.id,right=s.project.views.front.find(o=>o.instanceOf===id);assert.ok(right);app.setProperty('component:width',120);assert.equal(right.component.width,120);app.setProperty('y',300);assert.equal(bounds(left).y,bounds(right).y);await app.save(false);const saved=clone(records.get(s.project.id));app.open(saved);app.selectId(id,false,true);app.keyboard({key:'Escape',target:{tagName:'SVG'},preventDefault(){}});app.action('delete');assert.ok(!app.editorState().project.views.front.some(o=>o.id===id||o.instanceOf===id));app.undo();assert.ok(app.editorState().project.views.front.some(o=>o.instanceOf===id));});
test('V3 pencil through actual pointer handlers creates Bézier geometry, one undo step and procedural stitch',async()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.toolSet('pencil');const before=app.editorState().history.past.length;app.pointerDown(event(coord({x:130,y:250})));for(let i=1;i<100;i++)app.pointerMove(event(coord({x:130+i*2,y:250+Math.sin(i*.03)*30})));app.pointerUp(event(coord({x:328,y:250+Math.sin(99*.03)*30})));let o=selectedPath();assert.equal(o.semanticType,'freehand');assert.ok(o.nodes.some(n=>n.out));assert.ok(o.nodes.length<25);assert.equal(app.editorState().history.past.length,before+1);app.construction('stitch',2);assert.equal(selectedPath().rows,2);await app.save(false);app.open(clone(records.get(app.editorState().project.id)));assert.ok(app.editorState().project.views.front.some(o=>o.semanticType==='freehand'));});
test('V3 actual structural dimensions update back while this-view-only preserves back',()=>{app.open(newProject('pants'));app.selectId(bodyId(),false,true);let front=selectedPath(),back=app.editorState().project.views.back.find(o=>o.role==='body'),w=bounds(back).w;app.setProperty('w',bounds(front).w+40);assert.ok(Math.abs(bounds(back).w-w-40)<.01);app.setProperty('applyTo','this');const h=bounds(back).h;app.setProperty('h',bounds(front).h-40);assert.equal(bounds(back).h,h);assert.ok(app.editorState().project.garment.diverged.length);app.undo();assert.ok(Math.abs(bounds(back).h-h)<.01);});
