test('V3 Alt-click cycles overlaps without duplicating; Alt-drag still creates one undo action',()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.addResource('seam',{x:200,y:200});const first=selectedPath().id;app.duplicate(0,0);const second=selectedPath().id,count=app.editorState().project.views.front.length;const center=bounds(selectedPath()),pos={x:center.x+center.w/2,y:center.y+center.h/2};app.pointerDown(event(coord(pos),undefined,{altKey:true}));app.pointerUp(event(coord(pos)));assert.equal(app.editorState().project.views.front.length,count);assert.equal(app.editorState().selected[0],first);app.pointerDown(event(coord(pos),undefined,{altKey:true}));app.pointerUp(event(coord(pos)));assert.equal(app.editorState().selected[0],second);});


