test('Refinement: segment drag changes curve handles but preserves anchors and other sections',()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.toolSet('rect');app.pointerDown(event(coord({x:100,y:100})));app.pointerMove(event(coord({x:300,y:200})));app.pointerUp(event(coord({x:300,y:200})));app.toolSet('node');const before=clone(selectedPath().nodes);app.pointerDown(event(coord({x:200,y:100})));app.pointerMove(event(coord({x:200,y:125})));app.pointerUp(event(coord({x:200,y:125})));const after=selectedPath().nodes;assert.deepEqual(after.map(n=>({x:n.x,y:n.y})),before.map(n=>({x:n.x,y:n.y})));assert.ok(after[0].out.y>100);assert.ok(after[1].in.y>100);assert.deepEqual(after[2],before[2]);});
