test('V4 command acceptance: mirror Double Stitch edits, deletes and restores both without losing pockets',()=>{get('modal').close();app.open(newProject('shorts'));app.addResource('pocket-cargoFlap',{x:250,y:310});const pocket=selectedPath(),id=pocket.id,initial=app.editorState().project.views.front.filter(o=>o.component?.kind==='pocket').length;app.selectId(id,false,true);const past=app.editorState().history.past.length;app.construction('stitch',2);let stitches=app.editorState().project.views.front.filter(o=>o.type==='stitch'&&[id,...app.editorState().project.views.front.filter(o=>o.instanceOf===id).map(o=>o.id)].includes(o.source));assert.equal(stitches.length,2);assert.equal(app.editorState().history.past.length,past+1);app.setConstructionProperty('offset',12);assert.ok(stitches.every(o=>o.offset===12));const stitchIds=stitches.map(o=>o.id);app.selectId(stitches[0].id,false,true);app.keyboard({key:'Delete',target:{tagName:'SVG'},preventDefault(){}});assert.ok(stitchIds.every(id=>!app.editorState().project.views.front.some(o=>o.id===id)));assert.equal(app.editorState().project.views.front.filter(o=>o.component?.kind==='pocket').length,initial);app.undo();assert.ok(stitchIds.every(id=>app.editorState().project.views.front.some(o=>o.id===id)));});
