test('V4 selected semantic modifier Delete and eraser click preserve base; undo restores each',()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.toolSet('rect');app.pointerDown(event(coord({x:100,y:100})));app.pointerMove(event(coord({x:220,y:220})));app.pointerUp(event(coord({x:220,y:220})));const id=selectedPath().id;app.addModifier('stitch',{offset:8,rows:2});app.keyboard({key:'Delete',target:{tagName:'SVG'},preventDefault(){}});assert.equal(selectedPath().id,id);assert.equal(selectedPath().modifiers.length,0);app.undo();assert.equal(selectedPath().modifiers.length,1);app.toolSet('eraser');app.pointerMove(event(coord({x:150,y:108})));assert.ok(get('selection').innerHTML.includes('erase-highlight'));app.pointerDown(event(coord({x:150,y:108})));assert.equal(app.editorState().project.views.front.find(o=>o.id===id).modifiers.length,0);assert.equal(app.editorState().project.views.front.find(o=>o.id===id).nodes.length,4);app.undo();assert.equal(app.editorState().project.views.front.find(o=>o.id===id).modifiers.length,1);});
test('V4 whole pants Stack previews two hems; Apply and palette intensity remain localized and undoable',()=>{app.open(newProject('pants'));app.selectId(bodyId(),false,true);const id=selectedPath().id,nodes=clone(selectedPath().nodes),past=app.editorState().history.past.length;app.addModifier('fabricFall',{length:80,intensity:6});assert.equal(selectedPath().modifiers?.length||0,0);assert.equal(app.editorState().edgeIds.length,2);assert.ok(!get('edge-confirm').classList.contains('hidden'));get('apply-edge-stack').onclick();assert.equal(app.editorState().history.past.length,past+1);assert.equal(selectedPath().modifiers[0].edgeIds.length,2);assert.deepEqual(selectedPath().nodes,nodes);assert.ok(get('construction-palette').innerHTML.includes('Caída / Stack'));get('construction-palette').onchange({target:{dataset:{constructionParam:'intensity'},type:'number',value:'9'}});assert.equal(selectedPath().modifiers[0].intensity,9);assert.equal(app.editorState().project.views.back.find(o=>o.role==='body').modifiers[0].intensity,9);app.undo();assert.equal(selectedPath().modifiers[0].intensity,6);app.undo();assert.equal(app.editorState().project.views.front.find(o=>o.id===id).modifiers?.length||0,0);});
