test('Siluetra object Cmd toggle, group menu, group transforms and lock/hide/undo are real commands',()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.addResource('cargo',{x:230,y:260});const pocket=selectedPath().id;app.addResource('jacketZip',{x:270,y:265});const zip=selectedPath().id;app.selectTreeObject(pocket,{});app.selectTreeObject(zip,{ctrlKey:true});assert.ok(app.editorState().selected.includes(pocket));assert.ok(app.editorState().selected.includes(zip));app.action('group');const g=app.editorState().project.groups.front.at(-1);assert.ok(g);const groupIds=app.editorState().selected,initial=app.editorState().project.views.front.filter(o=>!o.source&&(groupIds.includes(o.id)||app.editorState().project.views.front.some(e=>groupIds.includes(e.id)&&e.source===o.id))).map(o=>[o.id,o.matrix[4]]);app.setProperty('x',300);for(const [id,x]of initial)assert.notEqual(app.editorState().project.views.front.find(o=>o.id===id).matrix[4],x);app.action('hideSelection');assert.equal(app.editorState().project.groups.front.find(v=>v.id===g.id).hidden,true);app.action('lockSelection');const before=JSON.stringify(app.editorState().project.views);app.setProperty('x',420);assert.equal(JSON.stringify(app.editorState().project.views),before);app.ungroup();assert.ok(!app.editorState().project.groups.front.some(v=>v.id===g.id));app.undo();assert.ok(app.editorState().project.groups.front.some(v=>v.id===g.id))});

