test('Siluetra group names and semantic children survive duplicate, save/load and undo',async()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.toolSet('rect');app.pointerDown(event(coord({x:100,y:100})));app.pointerMove(event(coord({x:200,y:180})));app.pointerUp(event(coord({x:200,y:180})));app.construction('stitch',2);const seam=selectedPath(),source=seam.source;app.selectTreeObject(source,{});app.selectTreeObject(seam.id,{ctrlKey:true});app.group();const g=app.editorState().project.groups.front.at(-1);g.name='Zip Pocket';app.duplicate();assert.ok(app.editorState().project.groups.front.some(v=>v.name==='Zip Pocket — copia'));assert.ok(app.editorState().project.views.front.some(v=>v.type==='stitch'&&v.rows===2));await app.save(false);const saved=clone(records.get(app.editorState().project.id));app.open(saved);assert.ok(app.editorState().project.groups.front.some(v=>v.name==='Zip Pocket'));assert.ok(app.editorState().project.views.front.some(v=>v.source))});

test('Siluetra Delete on a semantic group deletes the assembly and Undo restores geometry and effects',()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.toolSet('rect');app.pointerDown(event(coord({x:120,y:200})));app.pointerMove(event(coord({x:220,y:280})));app.pointerUp(event(coord({x:220,y:280})));const base=selectedPath().id;app.construction('stitch',2);const seam=selectedPath().id;app.selectTreeObject(base,{});app.selectTreeObject(seam,{ctrlKey:true});app.group();const g=app.editorState().project.groups.front.at(-1);app.action('delete');assert.equal(app.editorState().project.views.front.length,0);assert.equal(app.editorState().project.groups.front.length,0);app.undo();assert.equal(app.editorState().project.views.front.length,2);assert.ok(app.editorState().project.groups.front.some(v=>v.id===g.id));assert.equal(app.editorState().project.views.front.find(v=>v.type==='stitch').rows,2)});

test('V7 complete document → curved panel → fills → boundary double stitch → edit → delete/undo → save/export workflow',async()=>{app.newDocument();get('modal').onclick({target:{closest:s=>s==='[data-new]'?{dataset:{new:'hoodie'}}:null}});app.createDocument(get('modal'),{width:2000,height:2000,unit:'px',ppi:300,background:'white'});const doc=app.editorState().project,body=doc.views.front.find(o=>o.role==='body'),b=bounds(body),y=b.y+b.h*.46;assert.equal(doc.document.widthPx,2000);assert.equal(doc.centerAxis,1000);app.toolSet('pen');const a={x:b.x-80,y},z={x:b.x+b.w+80,y};app.pointerDown(event(coord(a)));app.pointerMove(event(coord({x:a.x+80,y:y-35})));app.pointerUp(event(coord(a)));app.pointerDown(event(coord(z)));app.pointerMove(event(coord({x:z.x+80,y:y+35})));app.pointerUp(event(coord(z)));app.keyboard({key:'Enter',target:{tagName:'SVG'},preventDefault(){}});app.toolSet('select');const line=selectedPath();assert.ok(!line.closed&&line.nodes.length===2);const before=clone(app.editorState().project);app.beginPanelPreview(body.id);assert.equal(get('panel-preview').classList.contains('hidden'),false);assert.match(get('draft').innerHTML,/opacity=".24"/);app.confirmPanels();let s=app.editorState(),regions=s.project.views.front.filter(o=>o.panelOf===body.id&&o.semanticType==='region');assert.equal(regions.length,2);assert.equal(s.history.past.at(-1).views.front.filter(o=>o.semanticType==='region').length,0);const [upper,lower]=regions;app.applyColor('#000000',[upper.id]);app.applyColor('#888888',[lower.id]);app.selectId(upper.id,false,true);app.action('boundaryStitch');s=app.editorState();const seam=s.project.views.front.find(o=>o.source===line.id);assert.equal(seam.rows,2);app.selectId(line.id,false,true);app.toolSet('node');const cut=s.project.views.front.find(o=>o.id===line.id),node=clone(cut.nodes[0]);const target={closest:sel=>sel==='[data-node]'?{dataset:{node:'0',side:'out'}}:null};const start=point(cut.matrix,node.out);app.pointerDown(event(coord(start),target));app.pointerMove(event(coord({x:start.x,y:start.y-30})));app.pointerUp(event(coord({x:start.x,y:start.y-30})));s=app.editorState();assert.equal(s.project.views.front.find(o=>o.id===upper.id).fill,'#000000');assert.equal(s.project.views.front.find(o=>o.id===lower.id).fill,'#888888');const svg=exportSvg(s.project,'front','document');assert.match(svg,/width="2000" height="2000"/);assert.match(svg,/#000000/);assert.match(svg,/#888888/);assert.match(svg,/stroke-dasharray/);app.toolSet('select');app.selectId(line.id,false,true);app.action('delete');assert.equal(app.editorState().project.views.front.filter(o=>o.panelOf===body.id).length,0);app.undo();assert.equal(app.editorState().project.views.front.filter(o=>o.panelOf===body.id&&o.semanticType==='region').length,2);await app.save(false);const saved=clone(records.get(app.editorState().project.id));app.open(saved);assert.equal(app.editorState().project.document.ppi,300);assert.equal(app.editorState().project.views.front.find(o=>o.id===upper.id).fill,'#000000');});

test('V7 canvas Ctrl/Cmd toggles share selection with Objects, and marquee replace/add/subtract works after zoom',()=>{app.open(newProject('blank'));app.editorState().project.liveMirror=false;const draw=(x,y)=>{app.toolSet('rect');app.pointerDown(event(coord({x,y})));app.pointerMove(event(coord({x:x+20,y:y+20})));app.pointerUp(event(coord({x:x+20,y:y+20})));return selectedPath().id;},a=draw(20,20),b=draw(60,20),c=draw(100,20),d=draw(150,20);app.toolSet('select');app.selectId(a,false,true);app.pointerDown(event(coord({x:65,y:25}),undefined,{ctrlKey:true}));app.pointerUp(event(coord({x:65,y:25}),undefined,{ctrlKey:true}));assert.deepEqual(new Set(app.editorState().selected),new Set([a,b]));app.selectTreeObject(c,{ctrlKey:true});assert.equal(app.editorState().selected.length,3);app.pointerDown(event(coord({x:25,y:25}),undefined,{metaKey:true}));app.pointerUp(event(coord({x:25,y:25}),undefined,{metaKey:true}));assert.deepEqual(new Set(app.editorState().selected),new Set([b,c]));app.pointerDown(event(coord({x:10,y:10})));app.pointerMove(event(coord({x:125,y:45})));app.pointerUp(event(coord({x:125,y:45})));assert.deepEqual(new Set(app.editorState().selected),new Set([a,b,c]));app.pointerDown(event(coord({x:140,y:10}),undefined,{shiftKey:true}));app.pointerMove(event(coord({x:180,y:45}),undefined,{shiftKey:true}));app.pointerUp(event(coord({x:180,y:45}),undefined,{shiftKey:true}));assert.equal(app.editorState().selected.length,4);app.pointerDown(event(coord({x:10,y:10}),undefined,{altKey:true}));app.pointerMove(event(coord({x:45,y:45}),undefined,{altKey:true}));app.pointerUp(event(coord({x:45,y:45}),undefined,{altKey:true}));assert.deepEqual(new Set(app.editorState().selected),new Set([b,c,d]));app.keyboard({key:'g',ctrlKey:true,target:{tagName:'SVG'},preventDefault(){}});assert.ok(app.editorState().project.groups.front.length);app.undo();assert.equal(app.editorState().project.groups.front.length,0);});

test('V7 Fill tool clicks semantic panels, Eyedropper samples exact vector color, palette applies mixed selections and Escape closes only palette',()=>{app.open(newProject('blank'));app.editorState().project.liveMirror=false;const draw=(x)=>{app.toolSet('rect');app.pointerDown(event(coord({x,y:100})));app.pointerMove(event(coord({x:x+80,y:180})));app.pointerUp(event(coord({x:x+80,y:180})));return selectedPath().id;},a=draw(100),b=draw(220);app.toolSet('fill');app.setActiveColor('#c84040');app.pointerMove(event(coord({x:125,y:130})));assert.match(get('selection').innerHTML,/fill-hover/);app.pointerDown(event(coord({x:125,y:130})));assert.equal(selectedPath().fill,'#c84040');app.editorState().selected.splice(0);app.setActiveColor('#1f2428');app.pointerDown(event(coord({x:245,y:130})));assert.equal(selectedPath().fill,'#1f2428');app.undo();assert.equal(app.editorState().project.views.front.find(o=>o.id===b).fill,'#c84040');app.redo();assert.equal(app.editorState().project.views.front.find(o=>o.id===b).fill,'#1f2428');app.toolSet('eyedropper');app.pointerDown(event(coord({x:125,y:130})));assert.equal(app.editorState().project.colors.fill,'#c84040');app.toolSet('fill');app.pointerDown(event(coord({x:245,y:130})));assert.equal(selectedPath().fill,'#c84040');app.toolSet('select');app.selectId(a,false,true);app.selectId(b,true,true);app.applyColor('#26334f');assert.ok(app.editorState().project.views.front.every(o=>o.fill==='#26334f'));app.showColorPalette();const selected=[...app.editorState().selected];app.keyboard({key:'Escape',target:{tagName:'SVG'},preventDefault(){}});assert.deepEqual(app.editorState().selected,selected);assert.equal(get('color-palette').classList.contains('hidden'),true);});

test('V7 Fill hit order respects the painted pocket above generated body regions',()=>{app.open(newProject('hoodie'));const body=app.editorState().project.views.front.find(o=>o.role==='body'),b=bounds(body);app.toolSet('line');app.pointerDown(event(coord({x:b.x-30,y:b.y+b.h*.4})));app.pointerMove(event(coord({x:b.x+b.w+30,y:b.y+b.h*.4})));app.pointerUp(event(coord({x:b.x+b.w+30,y:b.y+b.h*.4})));app.beginPanelPreview(body.id);app.confirmPanels();const pocket=app.editorState().project.views.front.find(o=>o.closed&&/Bolsillo canguro/.test(o.name)),box=bounds(pocket),p={x:box.x+box.w/2,y:box.y+box.h/2};app.editorState().selected.splice(0);app.toolSet('fill');app.setActiveColor('#c84040');app.pointerDown(event(coord(p)));assert.equal(selectedPath().id,pocket.id);assert.equal(selectedPath().fill,'#c84040');assert.ok(app.editorState().project.views.front.filter(o=>o.semanticType==='region').every(o=>o.fill==='#fff'));});

test('V8 Bermuda Pencil command reproducer: left leg creates one linked counterpart',()=>{app.open(newProject('shorts'));assert.equal(app.editorState().project.liveMirror,true);app.toolSet('pencil');const ps=[{x:260,y:330},{x:275,y:345},{x:265,y:375},{x:290,y:395}];app.pointerDown(event(coord(ps[0])));for(const p of ps.slice(1))app.pointerMove(event(coord(p)));app.pointerUp(event(coord(ps.at(-1))));const s=app.editorState(),a=selectedPath(),b=s.project.views.front.find(o=>o.instanceOf===a.id);assert.ok(b,'Pencil left of axis must be linked');assert.equal(s.history.past.length,1);assert.equal(bounds(a).y,bounds(b).y);});

test('V8 Bermuda Pencil acceptance through command handlers: node, stroke, double stitch, delete, undo and Break',async()=>{app.open(newProject('shorts'));if(app.editorState().snap)get('snap').onclick();app.toolSet('pencil');const points=[{x:255,y:320},{x:272,y:335},{x:265,y:360},{x:280,y:385}];app.pointerDown(event(coord(points[0])));for(const p of points.slice(1))app.pointerMove(event(coord(p)));app.pointerUp(event(coord(points.at(-1))));let a=selectedPath(),id=a.id,p=app.editorState().project,b=p.views.front.find(o=>o.instanceOf===id);assert.ok(b);app.setProperty('stroke','#c84040');assert.equal(b.stroke,a.stroke);app.toolSet('node');const start=point(a.matrix,a.nodes[0]),target={closest:s=>s==='[data-node]'?{dataset:{node:'0'}}:null};app.pointerDown(event(coord(start),target));for(let i=1;i<=6;i++)app.pointerMove(event(coord({x:start.x-i,y:start.y+i})));app.pointerUp(event(coord({x:start.x-6,y:start.y+6})));a=selectedPath();assert.ok(Math.abs(a.nodes[0].x-start.x+6)<1e-8);assert.equal(point(a.matrix,a.nodes[0]).x+point(b.matrix,b.nodes[0]).x,700);app.toolSet('select');app.construction('stitch',2);const seam=selectedPath(),peer=p.views.front.find(o=>o.instanceOf===seam.id);assert.ok(peer);assert.equal(peer.rows,2);app.action('removeSelectedConstruction');assert.ok(!app.editorState().project.views.front.some(o=>o.id===seam.id||o.id===peer.id));app.undo();p=app.editorState().project;assert.equal(p.views.front.find(o=>o.id===peer.id).rows,2);app.selectId(id,false,true);app.action('breakSymmetry');p=app.editorState().project;b=p.views.front.find(o=>o.id===b.id);const old=clone(b);app.setProperty('stroke','#26334f');assert.deepEqual(b,old);await app.save(false);const saved=clone(records.get(p.id));app.open(saved);assert.ok(app.editorState().project.views.front.filter(o=>o.id===id||o.id===b.id).every(o=>!o.instanceOf&&!o.mirrorPeer));});

test('V8 reflected Pencil multi-event drag edits the canonical master every frame in one History action',()=>{app.open(newProject('shorts'));if(app.editorState().snap)get('snap').onclick();app.toolSet('pencil');app.pointerDown(event(coord({x:260,y:340})));app.pointerMove(event(coord({x:280,y:360})));app.pointerUp(event(coord({x:280,y:360})));const p=app.editorState().project,a=selectedPath(),b=p.views.front.find(o=>o.instanceOf===a.id);app.selectId(b.id,false,true);app.toolSet('node');const start=point(b.matrix,b.nodes[0]),target={closest:s=>s==='[data-node]'?{dataset:{node:'0'}}:null},before=app.editorState().history.past.length;app.pointerDown(event(coord(start),target));for(let i=1;i<=10;i++)app.pointerMove(event(coord({x:start.x+i,y:start.y+i})));app.pointerUp(event(coord({x:start.x+10,y:start.y+10})));assert.equal(point(b.matrix,b.nodes[0]).x,start.x+10);assert.equal(point(a.matrix,a.nodes[0]).x,700-start.x-10);assert.equal(app.editorState().history.past.length,before+1);});

test('V8 intrinsic right-side node multi-frame edits do not get overwritten by prior projected nodes',()=>{app.open(newProject('shorts'));if(app.editorState().snap)get('snap').onclick();app.selectId(bodyId(),false,true);app.toolSet('node');const a=selectedPath(),i=2,n=point(a.matrix,a.nodes[i]),target={closest:s=>s==='[data-node]'?{dataset:{node:String(i)}}:null};app.pointerDown(event(coord(n),target));for(let d=1;d<=8;d++)app.pointerMove(event(coord({x:n.x+d,y:n.y+d})));app.pointerUp(event(coord({x:n.x+8,y:n.y+8})));assert.ok(Math.abs(a.nodes[i].x-n.x-8)<1e-8);});

test('V9 Bermuda edge-to-edge drawing previews immediately, creates anchored panels, preserves fills through body edits and reload',async()=>{const {nearestBoundary}=await import('../dist/panel-cut.js');app.open(newProject('shorts'));if(app.editorState().snap)get('snap').onclick();const body=app.editorState().project.views.front.find(o=>o.role==='body'),left=nearestBoundary(body,{x:222,y:250}).point,right=nearestBoundary(body,{x:478,y:250}).point;app.selectId(body.id,false,true);app.toolSet('line');app.pointerDown(event(coord(left)));app.pointerMove(event(coord(right)));assert.match(get('draft').innerHTML,/opacity=".24"/);app.pointerUp(event(coord(right)));assert.match(get('panel-preview').innerHTML,/Crear paneles/);assert.ok(!get('panel-preview').innerHTML.includes('data-confirm-panels disabled'));const line=selectedPath(),before=app.editorState().history.past.length;app.confirmPanels();let p=app.editorState().project,regions=p.views.front.filter(o=>o.semanticType==='region');assert.equal(regions.length,2);assert.equal(app.editorState().history.past.length,before+1);assert.equal(line.boundaryAnchors.length,2);assert.ok(nearestBoundary(body,point(line.matrix,line.nodes[0])).distance<.005);const ids=regions.map(r=>r.id);app.selectId(ids[0],false,true);app.setProperty('fill','#26334f');app.selectId(body.id,false,true);app.setProperty('w',bounds(body).w+50);for(const n of [line.nodes[0],line.nodes.at(-1)])assert.ok(nearestBoundary(body,point(line.matrix,n)).distance<.005);assert.equal(p.views.front.find(o=>o.id===ids[0]).fill,'#26334f');await app.save(false);app.open(clone(records.get(p.id)));p=app.editorState().project;assert.equal(p.views.front.find(o=>o.id===line.id).boundaryAnchors.length,2);assert.deepEqual(p.views.front.filter(o=>o.semanticType==='region').map(o=>o.id),ids);});
test('V9 existing short path gives endpoint feedback and explicit Extend without a redraw',()=>{const p=newProject('blank');p.liveMirror=false;p.views.front=[...p.views.front];app.open(p);app.toolSet('rect');app.pointerDown(event(coord({x:100,y:100})));app.pointerMove(event(coord({x:400,y:400})));app.pointerUp(event(coord({x:400,y:400})));app.toolSet('line');app.pointerDown(event(coord({x:170,y:250})));app.pointerMove(event(coord({x:230,y:250})));app.pointerUp(event(coord({x:230,y:250})));app.beginPanelPreview();assert.match(get('panel-preview').innerHTML,/data-extend-panels/);assert.match(get('panel-preview').innerHTML,/data-confirm-panels disabled/);get('panel-preview').onclick({target:{closest:s=>s==='[data-extend-panels]'?{}:null}});assert.ok(!get('panel-preview').innerHTML.includes('data-confirm-panels disabled'));app.confirmPanels();const line=app.editorState().project.views.front.find(o=>o.semanticType==='panelBoundary');assert.equal(line.boundaryAnchors.length,2);assert.ok(Math.abs(line.nodes[0].x-100)<.005);assert.ok(Math.abs(line.nodes.at(-1).x-400)<.005);});
test('V9 attached endpoint drag updates its boundary position as one History action',async()=>{const {nearestBoundary}=await import('../dist/panel-cut.js');const p=newProject('blank');p.liveMirror=false;app.open(p);app.toolSet('rect');app.pointerDown(event(coord({x:100,y:100})));app.pointerMove(event(coord({x:400,y:400})));app.pointerUp(event(coord({x:400,y:400})));const base=selectedPath();app.toolSet('line');app.pointerDown(event(coord({x:100,y:250})));app.pointerMove(event(coord({x:400,y:250})));app.pointerUp(event(coord({x:400,y:250})));const line=selectedPath();app.confirmPanels();app.selectId(line.id,false,true);app.toolSet('node');const before=app.editorState().history.past.length,old=clone(line.boundaryAnchors),target={closest:s=>s==='[data-node]'?{dataset:{node:'1'}}:null};app.pointerDown(event(coord({x:400,y:250}),target));for(let d=1;d<=10;d++)app.pointerMove(event(coord({x:400-2/app.editorState().camera.z,y:250+d*2})));app.pointerUp(event(coord({x:400,y:270})));assert.ok(nearestBoundary(base,point(line.matrix,line.nodes.at(-1))).distance<.005);assert.ok(Math.abs(line.nodes.at(-1).y-270)<.01);assert.notEqual(line.boundaryAnchors[1].boundaryPosition,old[1].boundaryPosition);assert.equal(app.editorState().history.past.length,before+1);app.undo();assert.deepEqual(app.editorState().project.views.front.find(o=>o.id===line.id).boundaryAnchors,old);});

test('V10 color drag transaction previews live, commits once, and document Undo keeps Color open',()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.toolSet('rect');app.pointerDown(event(coord({x:100,y:100})));app.pointerMove(event(coord({x:200,y:200})));app.pointerUp(event(coord({x:200,y:200})));const id=selectedPath().id,prior=selectedPath().fill,n=app.editorState().history.past.length;app.showColorPalette();app.preview.begin('Cambiar relleno');for(const fill of ['#244466','#553388','#cc3344'])app.preview.update(p=>p.views.front.find(o=>o.id===id).fill=fill);assert.equal(selectedPath().fill,'#cc3344');assert.equal(app.editorState().history.past.length,n);app.preview.finish();assert.equal(app.editorState().history.past.length,n+1);app.keyboard({key:'z',ctrlKey:true,target:{tagName:'DIV'},preventDefault(){}});assert.equal(selectedPath().fill,prior);assert.equal(get('color-palette').classList.contains('hidden'),false);});
test('V10 selected fabric region retains base color and saves its pattern',async()=>{app.open(newProject('hoodie'));const body=app.editorState().project.views.front.find(o=>o.role==='body');app.selectId(body.id,false,true);app.applyColor('#263548');app.setFabric('waffle');assert.equal(selectedPath().fill,'#263548');assert.equal(selectedPath().fabricTexture.type,'waffle');app.applyColor('#cc3344');assert.equal(selectedPath().fabricTexture.type,'waffle');assert.match(exportSvg(app.editorState().project,'front'),/<pattern/);await app.save(false);const saved=clone(records.get(app.editorState().project.id));app.open(saved);app.selectId(body.id,false,true);assert.equal(selectedPath().fabricTexture.type,'waffle');app.setFabric('none');assert.equal(selectedPath().fill,'#cc3344');app.undo();assert.equal(selectedPath().fabricTexture.type,'waffle');});
test('V10 conversion is exact, one undo step, and Inspector offers summary rather than duplicate editor',()=>{app.open(newProject('blank'));app.editorState().project.liveMirror=false;app.toolSet('line');app.pointerDown(event(coord({x:100,y:100})));app.pointerMove(event(coord({x:250,y:150})));app.pointerUp(event(coord({x:250,y:150})));const id=selectedPath().id,nodes=clone(selectedPath().nodes),n=app.editorState().history.past.length;app.action('convert:stitch');assert.equal(selectedPath().construction.type,'stitch');assert.deepEqual(selectedPath().nodes,nodes);assert.equal(app.editorState().history.past.length,n+1);assert.match(get('construction-palette').innerHTML,/data-construction-param/);assert.doesNotMatch(get('properties').innerHTML,/data-construction-param/);app.undo();assert.equal(selectedPath().id,id);assert.equal(selectedPath().construction,undefined);app.redo();assert.equal(selectedPath().construction.type,'stitch');});
test('V10 resource accordions start closed and the library has one free Layers stack',()=>{app.open(newProject('hoodie'));tabs[0].onclick();const html=get('library-content').innerHTML;assert.doesNotMatch(html,/<details[^>]* open/);const body=app.editorState().project.views.front.find(o=>o.role==='body');app.selectId(body.id,false,true);assert.equal(app.editorState().tab,'resources');app.action('revealLayers');assert.match(get('library-content').innerHTML,/role="tree"/);assert.doesNotMatch(get('library-content').innerHTML,/object-category|data-category=/);assert.match(get('library-content').innerHTML,new RegExp(`data-layer-id="${body.id}"`));});

