test('V11 canvas click preserves Resources; explicit Reveal opens one logical mirror row',()=>{const p=newProject('blank');p.liveMirror=true;app.open(p);app.addResource('pocket-patch',{x:220,y:250});const o=selectedPath(),peer=app.editorState().project.views.front.find(x=>x.instanceOf===o.id);tabs[0].onclick();const b=bounds(peer);app.pointerDown(event(coord({x:b.x+b.w/2,y:b.y+b.h/2})));app.pointerUp(event(coord({x:b.x+b.w/2,y:b.y+b.h/2})));assert.equal(app.editorState().tab,'resources');app.action('revealLayers');const html=get('library-content').innerHTML;assert.equal((html.match(new RegExp(`data-layer-id="${o.id}"`,'g'))||[]).length,1);assert.ok(!html.includes(`data-layer-id="${peer.id}"`));assert.match(html,/layer-mirror-badge/);assert.match(html,new RegExp(`class="layer-row object-row active[^>]*data-layer-id="${o.id}"`));});
test('V11 generic selection never opens or leaves an empty Construction window',()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.addResource('seam',{x:200,y:200});const id=selectedPath().id;app.construction('stitch');app.action('editConstruction');assert.equal(get('construction-palette').classList.contains('hidden'),false);app.selectId(id,false,true);assert.equal(get('construction-palette').classList.contains('hidden'),true);app.renderConstructionPalette(true);assert.equal(get('construction-palette').classList.contains('hidden'),true);assert.equal(get('construction-palette').innerHTML,'');});
test('V11 Cuellos accordion renders six usable collar resources',()=>{app.open(newProject('blank'));tabs[0].onclick();assert.match(get('library-content').innerHTML,/data-resource-section="collars"/);for(const key of ['fine','wide','crew','mock','v','polo'])assert.match(get('library-content').innerHTML,new RegExp(`data-resource="collar-${key}"`));app.addResource('collar-wide');assert.equal(selectedPath().semanticType,'collar');assert.ok(selectedPath().nodes.length>=4);app.undo();assert.equal(app.editorState().project.views.front.length,0);});
test('V11 Panel command resolves an open Bézier boundary network and retains appearance after editing/reload',async()=>{const p=newProject('blank');p.liveMirror=false;const {makePath}=await import('../dist/core.js');const boundary=[makePath('Superior','M 100 100 C 180 80 320 80 400 100'),makePath('Derecha','M 400 100 L 400 400'),makePath('Inferior','M 400 400 L 100 400'),makePath('Izquierda','M 100 400 L 100 100')],cut=makePath('Corte','M 100 250 L 400 250');p.views.front=[...boundary,cut];app.open(p);app.selectId(cut.id,false,true);app.beginPanelPreview();assert.equal(app.editorState().panelPreview.valid,true);app.confirmPanels();const os=app.editorState().project.views.front,regions=os.filter(o=>o.semanticType==='region');assert.equal(regions.length,2);assert.deepEqual(os.find(o=>o.surfaceBoundaryIds).surfaceBoundaryIds.slice().sort(),boundary.map(o=>o.id).sort());app.selectId(regions[0].id,false,true);app.setFabric('waffle');await app.save(false);app.open(clone(records.get(p.id)));assert.equal(app.editorState().project.views.front.filter(o=>o.semanticType==='region').length,2);assert.ok(app.editorState().project.views.front.some(o=>o.fabricTexture?.type==='waffle'));});
test('V11 ambiguous panel targets enter whole-surface hover/click selection',async()=>{const {makePath}=await import('../dist/core.js'),p=newProject('blank');p.liveMirror=false;const a=makePath('A','M 100 100 L 300 100 L 300 300 L 100 300 Z','#fff'),b=makePath('B','M 100 100 L 300 100 L 300 300 L 100 300 Z','#fff'),cut=makePath('Corte','M 100 200 L 300 200');p.views.front=[a,b,cut];app.open(p);app.selectId(cut.id,false,true);app.beginPanelPreview();assert.equal(app.editorState().panelPreview.choosing,true);app.pointerMove(event(coord({x:200,y:150})));assert.match(get('draft').innerHTML,/fill="#56a287"/);app.pointerDown(event(coord({x:200,y:150})));assert.equal(app.editorState().panelPreview.baseId,b.id);assert.equal(app.editorState().panelPreview.valid,true);app.confirmPanels();assert.equal(app.editorState().project.views.front.filter(o=>o.panelOf===b.id&&o.semanticType==='region').length,2);});
test('V11 Construction eraser removes an embedded Stitch, preserves base, and Undo restores it',()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.toolSet('line');app.pointerDown(event(coord({x:100,y:200})));app.pointerMove(event(coord({x:400,y:200})));app.pointerUp(event(coord({x:400,y:200})));const id=selectedPath().id;app.addModifier('stitch',{offset:0});const nodes=clone(selectedPath().nodes);app.toolSet('eraser');app.setEraserMode('construction');const n=app.editorState().history.past.length;app.pointerDown(event(coord({x:200,y:200})));assert.deepEqual(app.editorState().project.views.front.find(o=>o.id===id).nodes,nodes);assert.equal(app.editorState().project.views.front.find(o=>o.id===id).modifiers.length,0);assert.equal(app.editorState().history.past.length,n+1);app.undo();assert.equal(app.editorState().project.views.front.find(o=>o.id===id).modifiers[0].type,'stitch');});
test('V11 Vector eraser drag partially cuts touched segments and commits one gesture',async()=>{const {makePath}=await import('../dist/core.js'),p=newProject('blank');p.liveMirror=false;const o=makePath('Vector','M 100 200 L 200 200 C 230 220 270 180 300 200 L 400 200'),other=makePath('Sin tocar','M 100 400 L 400 400');p.views.front=[o,other];app.open(p);app.toolSet('eraser');app.setEraserMode('vector');assert.match(get('hint').textContent,/segmentos vectoriales/);app.pointerDown(event(coord({x:250,y:150})));app.pointerMove(event(coord({x:250,y:250})));app.pointerUp(event(coord({x:250,y:250})));assert.equal(app.editorState().history.past.length,1);const os=app.editorState().project.views.front;assert.equal(os.length,3);assert.deepEqual(os.find(x=>x.id===other.id).nodes.map(n=>[n.x,n.y]),other.nodes.map(n=>[n.x,n.y]));assert.deepEqual(os.find(x=>x.id===o.id).nodes.slice(0,2).map(n=>[n.x,n.y]),[[100,200],[200,200]]);app.undo();assert.equal(app.editorState().project.views.front.length,2);assert.deepEqual(app.editorState().project.views.front.find(x=>x.id===o.id).nodes.map(n=>[n.x,n.y,n.in,n.out]),o.nodes.map(n=>[n.x,n.y,n.in,n.out]));});
test('V11 Fabric palette swatches use exported vector definitions rather than placeholder CSS',()=>{app.open(newProject('tee'));app.selectId(bodyId(),false,true);app.showFabricPalette();for(const type of ['jersey','fleece','waffle','terry','rib','denim','twill'])assert.match(get('fabric-palette').innerHTML,new RegExp(`data-fabric-type="${type}"`));assert.match(get('fabric-palette').innerHTML,/patternUnits="userSpaceOnUse"/);});

