// V13: actual UI adapters, not manual browser tests.
const uxEvent=id=>({target:{closest:s=>s==='[data-ux-command]'?{dataset:{uxCommand:id},disabled:false}:null}});
function independentRect(){const p=newProject('blank');p.liveMirror=false;app.open(p);app.toolSet('rect');app.pointerDown(event(coord({x:100,y:100})));app.pointerMove(event(coord({x:200,y:200})));app.pointerUp(event(coord({x:200,y:200})));return selectedPath();}
test('V13 toolbar flyout button activates Curvature without leaving Resources',()=>{app.open(newProject('blank'));get('tools').onclick({target:{closest:s=>s==='[data-tool]'?{dataset:{tool:'curvature'}}:null}});assert.equal(app.editorState().tool,'curvature');assert.match(get('context-bar').innerHTML,/Alt clic: esquina/);assert.equal(get('library-content').dataset.rendered,'resources');assert.match(get('tools').innerHTML,/data-family="pen"><button data-tool="curvature"/);});
test('V13 selection changes contextual tasks from document to vector to garment',()=>{independentRect();app.toolSet('select');assert.match(get('context-bar').innerHTML,/data-ux-command="simplify"/);app.open(newProject('tee'));assert.match(get('context-bar').innerHTML,/data-ux-command="importGraphic"/);app.selectId(bodyId(),false,true);assert.match(get('context-bar').innerHTML,/data-ux-command="createPanel"/);assert.ok(!get('context-bar').innerHTML.includes('data-ux-command="simplify"'));});
test('V13 Pathfinder popover buttons dispatch real union and Undo',()=>{const a=independentRect(),b=app.duplicate(30,0)[0];app.selectId(a.id,false,true);app.selectId(b,true,true);get('ux-menus').onclick(uxEvent('pathfinderPanel'));assert.match(get('pathfinder-popover').innerHTML,/data-ux-command="boolean:union"/);const past=app.editorState().history.past.length;get('pathfinder-popover').onclick(uxEvent('boolean:union'));assert.equal(app.editorState().project.views.front.length,1);assert.equal(app.editorState().history.past.length,past+1);app.undo();assert.equal(app.editorState().project.views.front.length,2);});
test('V13 UI command dispatcher blocks invalid geometry without mutation or history',()=>{app.open(newProject('tee'));app.selectId(bodyId(),false,true);const before=JSON.stringify(app.editorState().project),past=app.editorState().history.past.length;assert.equal(app.runCommand('simplify'),false);assert.equal(JSON.stringify(app.editorState().project),before);assert.equal(app.editorState().history.past.length,past);assert.match(get('status').textContent,/vinculada/);app.openPathfinder();assert.match(get('pathfinder-popover').innerHTML,/aria-disabled="true"/);});
test('V13 Inspector appearance and shear edits each use native history',()=>{independentRect();const before=clone(selectedPath().matrix),past=app.editorState().history.past.length;assert.match(get('properties').innerHTML,/data-prop="blendMode"/);assert.match(get('properties').innerHTML,/data-prop="lineCap"/);assert.match(get('properties').innerHTML,/data-prop="shearDelta"/);app.setProperty('blendMode','multiply');app.setProperty('lineCap','butt');app.setProperty('shearDelta',12);assert.equal(app.editorState().history.past.length,past+3);assert.equal(selectedPath().blendMode,'multiply');assert.equal(selectedPath().lineCap,'butt');assert.notDeepEqual(selectedPath().matrix,before);app.undo();assert.deepEqual(selectedPath().matrix,before);});
