test('V13 contextual gradient and reverse route to real native appearance',()=>{independentRect();get('context-bar').listeners.click(uxEvent('gradientFill'));assert.equal(app.editorState().tool,'gradient');assert.match(get('selection').innerHTML,/data-gradient-end="0"/);assert.match(get('context-bar').innerHTML,/data-ux-command="reverseGradient"/);const colors=selectedPath().gradient.stops.map(s=>s.color),past=app.editorState().history.past.length;app.runCommand('reverseGradient');assert.deepEqual(selectedPath().gradient.stops.map(s=>s.color),colors.reverse());assert.equal(app.editorState().history.past.length,past+1);app.undo();assert.deepEqual(selectedPath().gradient.stops.map(s=>s.color),colors.reverse());});
test('V13 gradient endpoint drag is visible, exact and cancelled on tool switch',()=>{independentRect();app.runCommand('gradientFill');const before=clone(selectedPath().gradient),past=app.editorState().history.past.length,target={closest:s=>s==='[data-gradient-end]'?{dataset:{gradientEnd:'1'}}:null};app.pointerDown(event(coord({x:200,y:150}),target));app.pointerMove(event(coord({x:180,y:120})));app.toolSet('select');assert.deepEqual(selectedPath().gradient,before);assert.equal(app.editorState().history.past.length,past);app.toolSet('gradient');app.pointerDown(event(coord({x:200,y:150}),target));app.pointerMove(event(coord({x:180,y:120})));app.pointerUp(event(coord({x:180,y:120})));assert.equal(selectedPath().gradient.x2,.8);assert.equal(selectedPath().gradient.y2,.2);assert.equal(app.editorState().history.past.length,past+1);app.undo();assert.deepEqual(selectedPath().gradient,before);});
test('V13 scissors hover previews actual point and protected garment gives prohibited feedback',()=>{const p=newProject('blank');p.liveMirror=false;app.open(p);app.toolSet('line');app.pointerDown(event(coord({x:100,y:100})));app.pointerMove(event(coord({x:200,y:100})));app.pointerUp(event(coord({x:200,y:100})));app.toolSet('scissors');app.pointerMove(event(coord({x:150,y:100})));assert.match(get('tool-feedback').innerHTML,/Cortar aquí/);app.open(newProject('tee'));app.selectId(bodyId(),false,true);const o=selectedPath(),pnt=point(o.matrix,o.nodes[0]);app.toolSet('scissors');app.pointerMove(event(coord(pnt)));assert.match(get('tool-feedback').innerHTML,/Prenda protegida/);assert.equal(get('canvas').style.cursor,'not-allowed');});
test('V13 measure readout appears in contextual controls and creates no history',()=>{app.open(newProject('blank'));app.toolSet('measure');const past=app.editorState().history.past.length;assert.match(get('context-bar').innerHTML,/id="measure-value"/);app.pointerDown(event(coord({x:10,y:10})));app.pointerMove(event(coord({x:40,y:50})));app.pointerUp(event(coord({x:40,y:50})));assert.match(get('measure-value').textContent,/Distancia 50\.00/);assert.equal(app.editorState().history.past.length,past);});
