test('Hardening: invalid project opening preserves document, selection and history',()=>{get('modal').close();app.open(newProject('tee'));app.selectId(bodyId(),false,true);const s=app.editorState(),p=clone(s.project),selected=[...s.selected],history=s.history;const bad=clone(p);bad.views.front[0].nodes={};assert.throws(()=>app.open(bad));assert.deepEqual(app.editorState().project,p);assert.deepEqual(app.editorState().selected,selected);assert.equal(app.editorState().history,history);});
test('Hardening: autosave cannot overwrite the persisted valid project with invalid transient geometry',async()=>{get('modal').close();app.open(newProject('blank'));app.addResource('seam',{x:200,y:200});await app.save(false);const s=app.editorState(),saved=clone(records.get(s.project.id));s.project.views.front[0].nodes[0].x=NaN;await app.save(false);assert.deepEqual(records.get(s.project.id),saved);assert.match(get('save-state').textContent,/inválido/);app.open(saved);});
test('Hardening: autosave during a color preview retains committed state until one final history action',async()=>{get('modal').close();app.open(newProject('blank'));app.addResource('pocket-cargoFlap',{x:250,y:250});const s=app.editorState(),id=selectedPath().id,initial=selectedPath().fill,past=s.history.past.length;app.preview.begin('Color');app.preview.update(()=>selectedPath().fill='#abcdef');assert.equal(get('active-fill').dataset.paintState,'solid');assert.equal(get('active-fill').style.background,'#abcdef');await app.save(false);assert.equal(records.get(s.project.id).views.front.find(o=>o.id===id).fill,initial);app.preview.finish();assert.equal(app.editorState().history.past.length,past+1);await app.save(false);assert.equal(records.get(s.project.id).views.front.find(o=>o.id===id).fill,'#abcdef');app.undo();assert.equal(selectedPath().fill,initial);app.redo();assert.equal(selectedPath().fill,'#abcdef');});
test('Hardening: opening a dialog cancels an unfinished canvas drag without committing',()=>{get('modal').close();app.open(newProject('blank'));app.addResource('pocket-cargoFlap',{x:250,y:250});const p=clone(app.editorState().project),past=app.editorState().history.past.length;app.toolSet('select');app.pointerDown(event(coord({x:250,y:260})));app.pointerMove(event(coord({x:310,y:310})));app.modal('<h2>Revisión</h2><button data-close>Cerrar</button>');assert.deepEqual(app.editorState().project,p);assert.equal(app.editorState().history.past.length,past);get('modal').close();});
test('Hardening: failed numeric preview restores valid geometry and leaves Undo usable',()=>{get('modal').close();app.open(newProject('blank'));app.addResource('seam',{x:220,y:220});const initial=clone(app.editorState().project),past=app.editorState().history.past.length;app.preview.begin('fault');assert.throws(()=>app.preview.update(()=>selectedPath().nodes[0].in={x:Infinity,y:0}));assert.deepEqual(app.editorState().project,initial);assert.equal(app.preview.active,false);assert.equal(app.editorState().history.past.length,past);app.undo();assert.equal(app.editorState().project.views.front.length,0);app.redo();assert.deepEqual(app.editorState().project,initial);});

test('edge-panel UI selects curved spans with independent temporary state, hover and click toggle; Escape writes nothing',()=>{const {p,body,a,b}=edgePanelDocument();app.open(p);app.selectId(body.id,false,true);const before=clone(app.editorState().project),selection=[...app.editorState().selected],count=app.editorState().history.past.length;app.beginPanelEdges();app.pointerMove(event(coord(cubic(a.nodes[0],a.nodes[1],.5))));assert.match(get('draft').innerHTML,/edge-hover/);edgePanelSelectCurves(a,b);let s=app.editorState();assert.equal(s.panelEdgeState.selection.selected.length,2);assert.equal(s.panelEdgeState.selection.candidates.length,2);assert.equal(s.panelEdgeState.selection.choice,null);assert.match(get('panel-preview').innerHTML,/Hay varias áreas posibles/);assert.match(get('panel-preview').innerHTML,/data-create-edge-panel disabled/);assert.deepEqual(s.project,before);assert.deepEqual(s.selected,selection);edgePanelClick(cubic(a.nodes[0],a.nodes[1],.5));assert.equal(app.editorState().panelEdgeState.selection.selected.length,1);app.keyboard({key:'Escape',target:{tagName:'SVG'},preventDefault(){}});assert.equal(app.editorState().panelEdgeState,null);assert.equal(get('draft').innerHTML,'');assert.deepEqual(app.editorState().project,before);assert.equal(app.editorState().history.past.length,count);assert.deepEqual(app.editorState().selected,selection);});
test('edge-panel UI chooses an ambiguous area, Enter creates one ordinary panel, color/fabric and Undo/Redo/save/export work',async()=>{const {p,body,a,b}=edgePanelDocument();app.open(p);app.selectId(body.id,false,true);app.beginPanelEdges();edgePanelSelectCurves(a,b);app.pointerMove(event(coord({x:240,y:150})));assert.match(get('draft').innerHTML,/panel-edge-region/);assert.equal(app.editorState().panelEdgeState.selection.choice,null,'hover does not authorize creation');edgePanelClick({x:240,y:150});assert.ok(app.editorState().panelEdgeState.selection.choice);assert.match(get('draft').innerHTML,/panel-edge-auto/);app.keyboard({key:'Enter',target:{tagName:'SVG'},preventDefault(){}});let s=app.editorState(),r=s.project.views.front.find(o=>o.semanticType==='region');assert.ok(r);assert.equal(r.panelOf,body.id);assert.equal(s.panelEdgeState,null);assert.equal(s.tool,'select');assert.deepEqual(s.selected,[r.id]);assert.equal(s.history.past.length,1);assert.ok(s.project.views.front.find(o=>o.id===a.id).modifiers.some(m=>m.id==='edge-seam'));app.undo();assert.ok(!app.editorState().project.views.front.some(o=>o.id===r.id));app.redo();app.selectId(r.id,false,true);app.applyColor('#dabb22');app.setFabric('waffle');await app.save(false);const saved=clone(records.get(app.editorState().project.id));app.open(saved);s=app.editorState();r=s.project.views.front.find(o=>o.id===r.id);assert.equal(r.fill,'#dabb22');assert.equal(r.fabricTexture.type,'waffle');assert.match(exportSvg(s.project,'front'),/data-region=/);assert.ok(s.project.views.front.find(o=>o.id===b.id));});
test('edge-panel UI auto-completion yields one region after choosing a garment boundary span, clear and checkbox recompute',()=>{const {p,body,a,b}=edgePanelDocument();app.open(p);app.selectId(body.id,false,true);app.beginPanelEdges();edgePanelSelectCurves(a,b);edgePanelClick({x:180,y:100});assert.equal(app.editorState().panelEdgeState.selection.candidates.length,1);assert.ok(app.editorState().panelEdgeState.selection.choice);assert.match(get('draft').innerHTML,/panel-edge-auto/);get('panel-preview').onchange({target:{matches:s=>s==='[data-auto-panel-outline]',checked:false}});assert.equal(app.editorState().panelEdgeState.selection.candidates.length,0);get('panel-preview').onchange({target:{matches:s=>s==='[data-auto-panel-outline]',checked:true}});assert.equal(app.editorState().panelEdgeState.selection.candidates.length,1);get('panel-preview').onclick({target:{closest:s=>s==='[data-clear-panel-edges]'?{}:null}});assert.equal(app.editorState().panelEdgeState.selection.selected.length,0);assert.match(get('panel-preview').innerHTML,/data-create-edge-panel disabled/);app.cancelPanelEdges();});
test('edge-panel tool switching and Front/Back change cancel preview without changing source geometry',()=>{const {p,body,a,b}=edgePanelDocument();p.views.back=[makePath('Espalda','M100 200L400 200','none')];app.open(p);app.selectId(body.id,false,true);const before=clone(app.editorState().project);app.beginPanelEdges();edgePanelSelectCurves(a,b);app.toolSet('pen');assert.equal(app.editorState().panelEdgeState,null);assert.equal(get('draft').innerHTML,'');assert.deepEqual(app.editorState().project,before);app.toolSet('select');app.beginPanelEdges();edgePanelSelectCurves(a,b);back.onclick();assert.equal(app.editorState().view,'back');assert.equal(app.editorState().panelEdgeState,null);assert.deepEqual(app.editorState().project,before);front.onclick();});
test('edge-panel eligibility respects hidden/locked parent groups, active view and graphic category in actual command',()=>{const {p,body,a,b}=edgePanelDocument(),hidden=makePath('Oculto','M100 150L400 150','none'),locked=makePath('Bloqueado','M100 170L400 170','none'),graphic=makePath('Gráfico','M100 180L400 180','none');hidden.group='hidden-folder';locked.locked=true;graphic.category='graphic';p.groups.front.push({id:'hidden-folder',name:'Oculto',hidden:true});p.views.front.push(hidden,locked,graphic);p.views.back.push(makePath('Atrás','M100 190L400 190','none'));app.open(p);app.selectId(body.id,false,true);app.beginPanelEdges();const t=app.editorState().panelEdgeState.selection.topology;assert.ok(!t.fragments.some(f=>f.refs.some(r=>[hidden.id,locked.id,graphic.id,p.views.back[0].id].includes(r.source))));app.cancelPanelEdges();});
test('edge-panel multiple garment pieces ask for the piece rather than borrowing arbitrary outline',()=>{const {p,body}=edgePanelDocument(),other=makePath('Otra pieza','M450 100L550 100L550 300L450 300Z','#fff');other.category='structure';p.views.front.push(other);app.open(p);app.beginPanelEdges();assert.equal(app.editorState().panelEdgeState.selection,null);assert.match(get('panel-preview').innerHTML,/Elegí la pieza/);edgePanelClick({x:200,y:200});assert.equal(app.editorState().panelEdgeState.surface.id,body.id);assert.ok(!app.editorState().panelEdgeState.selection.topology.fragments.some(f=>f.refs[0].source===other.id));app.cancelPanelEdges();});
test('edge-panel stale geometry invalidates cached selection before confirm, and modal cancels safely',()=>{const {p,body,a,b}=edgePanelDocument();app.open(p);app.selectId(body.id,false,true);app.beginPanelEdges();edgePanelSelectCurves(a,b);edgePanelClick({x:180,y:100});assert.ok(app.editorState().panelEdgeState.selection.choice);app.setProperty('w',330);assert.equal(app.editorState().panelEdgeState.selection.selected.length,0);app.confirmEdgePanel();assert.ok(!app.editorState().project.views.front.some(o=>o.semanticType==='region'));app.action('createPanel');assert.equal(app.editorState().panelEdgeState,null);assert.match(get('modal').innerHTML,/Dibujar división/);assert.match(get('modal').innerHTML,/Seleccionar bordes/);get('modal').close();});
test('existing invalid Draw Division keeps validation and offers Select Edges without deleting the line',()=>{const {p,body,a}=edgePanelDocument();app.open(p);app.selectId(a.id,false,true);app.beginPanelPreview(body.id);assert.equal(app.editorState().panelPreview.valid,false);assert.match(get('panel-preview').innerHTML,/data-select-panel-edges/);get('panel-preview').onclick({target:{closest:s=>s==='[data-select-panel-edges]'?{}:null}});assert.ok(app.editorState().panelEdgeState.selection);assert.equal(app.editorState().panelPreview,null);assert.ok(app.editorState().project.views.front.some(o=>o.id===a.id));app.cancelPanelEdges();});

test('edge-panel zoom adapts the two-pixel joining tolerance without losing selected spans or choosing an ambiguous face',()=>{const {p,body,a,b}=edgePanelDocument();app.open(p);app.selectId(body.id,false,true);app.beginPanelEdges();edgePanelSelectCurves(a,b);const selectedCount=app.editorState().panelEdgeState.selection.selected.length;app.keyboard({key:'+',ctrlKey:true,target:{tagName:'SVG'},preventDefault(){}});const s=app.editorState(),op=s.panelEdgeState.selection;assert.equal(op.selected.length,selectedCount);assert.equal(op.choice,null);assert.ok(op.topology.tolerance*s.camera.z<=2+1e-9);app.cancelPanelEdges();});
test('edge-panel invalidated source edits show a simple recovery message in the normal Inspector',()=>{const {p,body,a,b}=edgePanelDocument();app.open(p);app.selectId(body.id,false,true);app.beginPanelEdges();edgePanelSelectCurves(a,b);edgePanelClick({x:180,y:100});app.confirmEdgePanel();const r=selectedPath(),source=app.editorState().project.views.front.find(o=>o.id===b.id);app.selectId(b.id,false,true);app.setProperty('x',bounds(source).x+30);app.selectId(r.id,false,true);app.properties();assert.match(get('properties').innerHTML,/Conservamos el último panel válido/);});

test('selecting another piece in Layers cancels edge-panel state and restores normal selection',()=>{const {p,body,a,b}=edgePanelDocument();app.open(p);app.selectId(body.id,false,true);app.beginPanelEdges();edgePanelSelectCurves(a,b);const before=clone(app.editorState().project);app.selectTreeObject(a.id,{});assert.equal(app.editorState().panelEdgeState,null);assert.deepEqual(app.editorState().selected,[a.id]);assert.deepEqual(app.editorState().project,before);assert.equal(get('draft').innerHTML,'');});

function enterOwnerEdges(){app.action('selectPanelEdges');return app.editorState().panelEdgeState;}
function twoOwnerDocument(){const d=edgePanelDocument(),other=makePath('Manga independiente','M450 100L650 100L650 500L450 500Z','#fff');other.category='structure';d.p.views.front.push(other);return {...d,other};}
function escapePanel(){app.keyboard({key:'Escape',target:{tagName:'SVG'},preventDefault(){}});}
test('owner regression: current Canvas selection is used before multiple-owner inference',()=>{const {p,body}=twoOwnerDocument();app.open(p);edgePanelClick({x:180,y:180});assert.deepEqual(app.editorState().selected,[body.id]);const op=enterOwnerEdges();assert.equal(op.surface.id,body.id);assert.equal(op.phase,'SELECT_EDGES');assert.equal(get('hint').textContent,'Seleccioná los bordes que forman el panel.');app.cancelPanelEdges();});
test('owner regression: no preselection infers the only traced garment surface',()=>{const {p,body}=tracedTorsoDocument();app.open(p);const before=clone(app.editorState().project),op=enterOwnerEdges();assert.ok(op.surface.boundaryIds.includes(body.id));assert.equal(op.phase,'SELECT_EDGES');assert.deepEqual(app.editorState().selected,[]);assert.deepEqual(app.editorState().project,before);app.cancelPanelEdges();});
test('owner regression: multiple garments highlight in owner-pick phase with pick cursor',()=>{const {p,other}=twoOwnerDocument();app.open(p);const op=enterOwnerEdges();assert.equal(op.phase,'RESOLVE_OWNER');assert.equal(get('canvas').style.cursor,'default');assert.match(get('hint').textContent,/Elegí la pieza donde/);app.pointerMove(event(coord({x:550,y:200})));assert.match(get('draft').innerHTML,/panel-edge-region/);assert.equal(get('canvas').style.cursor,'pointer');assert.equal(op.selection,null);assert.deepEqual(app.editorState().selected,[]);app.cancelPanelEdges();});
test('owner regression: first pointerdown resolves garment and pointerup does not swallow transition',()=>{const {p,other}=twoOwnerDocument();app.open(p);const before=clone(app.editorState().project),op=enterOwnerEdges();app.pointerDown(event(coord({x:550,y:200})));assert.equal(op.surface.id,other.id);assert.equal(op.phase,'SELECT_EDGES');assert.equal(op.selection.selected.length,0,'owner click must not also pick an edge');app.pointerUp(event(coord({x:550,y:200})));assert.equal(op.phase,'SELECT_EDGES');assert.deepEqual(app.editorState().project,before);app.cancelPanelEdges();});
test('owner regression: hover is active immediately after canvas owner pick',()=>{const {p}=twoOwnerDocument();app.open(p);enterOwnerEdges();edgePanelClick({x:550,y:200});app.pointerMove(event(coord({x:550,y:100})));const op=app.editorState().panelEdgeState;assert.ok(op.selection.hover);assert.match(get('draft').innerHTML,/edge-hover/);assert.match(get('draft').innerHTML,/panel-edge-owner/);app.cancelPanelEdges();});
test('owner regression: subsequent canvas click adds an edge without changing Layers selection',()=>{const {p,other}=twoOwnerDocument();app.open(p);enterOwnerEdges();edgePanelClick({x:550,y:200});edgePanelClick({x:550,y:100});const op=app.editorState().panelEdgeState;assert.equal(op.surface.id,other.id);assert.equal(op.selection.selected.length,1);assert.deepEqual(app.editorState().selected,[]);app.cancelPanelEdges();});
for(const link of ['ownerId','panelOf','source','attachment'])test('owner regression: selected semantic child resolves owner through '+link,()=>{const {p,body,other}=twoOwnerDocument(),child=makePath('Costura asociada','M100 150L400 150','none');if(link==='attachment')child.attachment={source:body.id};else child[link]=body.id;p.views.front.push(child);app.open(p);app.selectTreeObject(child.id,{});const op=enterOwnerEdges();assert.equal(op.surface.id,body.id);assert.equal(op.phase,'SELECT_EDGES');assert.deepEqual(app.editorState().selected,[child.id]);app.cancelPanelEdges();});
test('owner regression: random graphic selection falls back to one available owner',()=>{const {p,body}=edgePanelDocument(),graphic=makePath('Gráfico','M700 100L800 100L800 200L700 200Z','#fff');graphic.category='graphic';p.views.front.push(graphic);app.open(p);app.selectTreeObject(graphic.id,{});const op=enterOwnerEdges();assert.equal(op.surface.id,body.id);assert.equal(op.phase,'SELECT_EDGES');assert.deepEqual(app.editorState().selected,[graphic.id]);app.cancelPanelEdges();});
test('owner regression: invalid graphic with multiple garments enters pick and can transition',()=>{const {p,other}=twoOwnerDocument(),graphic=makePath('Gráfico','M700 100L800 100L800 200L700 200Z','#fff');graphic.category='graphic';p.views.front.push(graphic);app.open(p);app.selectTreeObject(graphic.id,{});const op=enterOwnerEdges();assert.equal(op.phase,'RESOLVE_OWNER');edgePanelClick({x:550,y:200});assert.equal(op.surface.id,other.id);assert.equal(op.phase,'SELECT_EDGES');assert.deepEqual(app.editorState().selected,[graphic.id]);app.cancelPanelEdges();});
test('owner regression: Escape during owner pick restores ordinary canvas selection with no mutation',()=>{const {p,body}=twoOwnerDocument();app.open(p);const before=clone(app.editorState().project);enterOwnerEdges();escapePanel();assert.equal(app.editorState().panelEdgeState,null);assert.equal(app.editorState().tool,'select');assert.equal(get('canvas').style.cursor,'default');assert.deepEqual(app.editorState().project,before);edgePanelClick({x:180,y:180});assert.deepEqual(app.editorState().selected,[body.id]);});
test('owner regression: Escape during edge selection keeps preselection and source unchanged',()=>{const {p,body}=tracedTorsoDocument();app.open(p);app.selectTreeObject(body.id,{});const before=clone(app.editorState().project);enterOwnerEdges();edgePanelClick({x:180,y:100});assert.equal(app.editorState().panelEdgeState.selection.selected.length,1);escapePanel();assert.equal(app.editorState().panelEdgeState,null);assert.deepEqual(app.editorState().selected,[body.id]);assert.deepEqual(app.editorState().project,before);assert.equal(app.editorState().history.past.length,0);});
test('owner regression: switching tools during owner pick removes interception',()=>{const {p}=twoOwnerDocument();app.open(p);const before=clone(app.editorState().project);enterOwnerEdges();app.toolSet('pen');assert.equal(app.editorState().panelEdgeState,null);assert.equal(app.editorState().tool,'pen');assert.deepEqual(app.editorState().project,before);app.toolSet('select');});
test('owner regression: screenshot workflow selects Torso span and independent Bézier, enables preview and Create Panel',()=>{const {p,body}=tracedTorsoDocument(),curve=makePath('Trazado Bézier','M100 240C200 200 300 320 400 320','none');p.views.front=[body,curve];app.open(p);app.selectTreeObject(body.id,{});app.action('createPanel');get('modal').onclick({target:{closest:s=>s==='[data-panel-method]'?{dataset:{panelMethod:'edges'}}:null}});const op=app.editorState().panelEdgeState;assert.equal(op.phase,'SELECT_EDGES');assert.match(get('panel-preview').innerHTML,/Seleccioná los bordes que forman el panel/);app.pointerMove(event(coord({x:180,y:100})));assert.ok(op.selection.hover);edgePanelClick({x:180,y:100});edgePanelClick(cubic(curve.nodes[0],curve.nodes[1],.5));assert.equal(op.selection.selected.length,2);assert.equal(op.phase,'READY_TO_CREATE');assert.ok(op.selection.choice);assert.match(get('draft').innerHTML,/panel-edge-auto/);assert.doesNotMatch(get('panel-preview').innerHTML,/data-create-edge-panel disabled/);assert.deepEqual(app.editorState().selected,[body.id]);get('panel-preview').onclick({target:{closest:s=>s==='[data-create-edge-panel]'?{}:null}});assert.equal(app.editorState().panelEdgeState,null);assert.ok(app.editorState().project.views.front.some(o=>o.semanticType==='region'));assert.ok(app.editorState().project.views.front.some(o=>o.id===curve.id));const reopened=enterOwnerEdges();assert.equal(reopened.phase,'SELECT_EDGES');assert.equal(reopened.surface.id,app.editorState().project.views.front.find(o=>o.semanticType==='region').panelOf);app.cancelPanelEdges();});
test('owner regression: genuinely incomplete contour reports an actionable error instead of an endless owner prompt',()=>{const p=newProject('blank');p.views.front=[makePath('Torso abierto','M100 100L400 100L400 500','none')];app.open(p);app.selectTreeObject(p.views.front[0].id,{});const before=clone(app.editorState().project),op=enterOwnerEdges();assert.equal(op.phase,'ERROR');assert.match(get('panel-preview').innerHTML,/Conectá los extremos/);app.pointerDown(event(coord({x:180,y:100})));escapePanel();assert.deepEqual(app.editorState().project,before);});
test('owner regression: independent divider touching the open-loop start does not hide Torso owner',()=>{const {p,body}=tracedTorsoDocument();p.views.front.push(makePath('División independiente','M100 100L250 500','none'));app.open(p);app.selectTreeObject(body.id,{});const op=enterOwnerEdges();assert.ok(op.surface.boundaryIds.includes(body.id));assert.equal(op.phase,'SELECT_EDGES');app.pointerMove(event(coord({x:180,y:100})));assert.ok(op.selection.hover);app.cancelPanelEdges();});
test('owner regression: selecting an unrelated image infers only garment, not image bounds',()=>{const {p,body}=edgePanelDocument();p.views.front.push({id:'owner-graphic-image',type:'image',name:'Logo',src:'data:image/png;base64,AA==',w:100,h:80,matrix:[1,0,0,1,700,600],opacity:1});app.open(p);app.selectTreeObject('owner-graphic-image',{});const op=enterOwnerEdges();assert.equal(op.surface.id,body.id);assert.equal(op.phase,'SELECT_EDGES');app.cancelPanelEdges();});
test('owner regression: semantic ownership walks multiple levels and terminates dependency cycles',()=>{const {p,body}=twoOwnerDocument(),a=makePath('Costura hija','M100 150L400 150','none'),b=makePath('Construcción nieta','M100 160L400 160','none');a.ownerId=body.id;a.attachment={source:b.id};b.ownerId=a.id;p.views.front.push(a,b);app.open(p);app.selectTreeObject(b.id,{});const op=enterOwnerEdges();assert.equal(op.surface.id,body.id);assert.equal(op.phase,'SELECT_EDGES');app.cancelPanelEdges();});

test("Polygonize acceptance: screenshot sleeve enters region mode through real editor handlers",()=>{const {p,torso}=visualHoodie();app.open(p);app.selectTreeObject(torso.id,{});app.action("selectPanelEdges");assert.equal(app.editorState().panelEdgeState.phase,"SELECT_EDGES");app.cancelPanelEdges();});
function chooseVisualArea(p){app.pointerMove(event(coord(p)));app.pointerDown(event(coord(p)));app.pointerUp(event(coord(p)));}
function beginAreaViaModal(){app.action('createPanel');assert.ok(get('modal').innerHTML.indexOf('Elegir área')<get('modal').innerHTML.indexOf('Seleccionar bordes'));get('modal').onclick({target:{closest:s=>s==='[data-panel-method]'?{dataset:{panelMethod:'area'}}:null}});return app.editorState().panelEdgeState;}
test('Polygonize area workflow: real sleeve hover, click, Enter creates normal editable panel and preserves sources',async()=>{const {p,torso,sleeve,inside,outside}=visualHoodie();app.open(p);app.selectTreeObject(torso.id,{});const before=clone(app.editorState().project),sources=clone(app.editorState().project.views.front.filter(o=>[torso.id,sleeve.id].includes(o.id))),op=beginAreaViaModal();assert.equal(op.phase,'SELECT_AREA');assert.equal(op.mode,'area');assert.match(get('context-bar').innerHTML,/Crear panel · Elegir área/);assert.equal(op.selection.topology.candidates.length,1);assert.equal(op.selection.choice,null);assert.match(get('panel-preview').innerHTML,/data-create-edge-panel disabled/);app.pointerMove(event(coord(inside)));assert.match(get('draft').innerHTML,/panel-edge-region/);assert.equal(op.selection.choice,null,'hover does not commit or authorize');assert.equal(get('canvas').style.cursor,'pointer');assert.deepEqual(app.editorState().project,before);app.pointerMove(event(coord(outside)));assert.doesNotMatch(get('draft').innerHTML,/panel-edge-region/);chooseVisualArea(inside);assert.equal(op.phase,'READY_TO_CREATE');assert.doesNotMatch(get('panel-preview').innerHTML,/data-create-edge-panel disabled/);app.keyboard({key:'Enter',target:{tagName:'SVG'},preventDefault(){}});let s=app.editorState(),r=selectedPath();assert.equal(r.semanticType,'region');assert.equal(r.panelEdgeSelection.backend,'turf-polygonize-v1');assert.ok(r.nodes.some(n=>n.in||n.out));assert.equal(s.panelEdgeState,null);assert.equal(s.history.past.length,1);assert.deepEqual(s.project.views.front.filter(o=>[torso.id,sleeve.id].includes(o.id)),sources);app.applyColor('#d9b824');app.setFabric('waffle');r=selectedPath();assert.equal(r.fill,'#d9b824');assert.equal(r.fabricTexture.type,'waffle');assert.match(exportSvg(s.project,'front'),/data-region=/);assert.match(exportSvg(s.project,'front'),/C /);await app.save(false);app.open(clone(records.get(s.project.id)));const loaded=app.editorState().project.views.front.find(o=>o.id===r.id);assert.equal(loaded.fill,'#d9b824');assert.equal(loaded.fabricTexture.type,'waffle');assert.equal(loaded.panelEdgeInvalid,undefined);});
test('Polygonize Select Edges on screenshot fixture finds the same curved area as area picking',()=>{const {p,torso,sleeve,inside}=visualHoodie();app.open(p);app.action('selectPanelEdges');const op=app.editorState().panelEdgeState,area=op.selection.topology.candidates[0],edge=cubic(torso.nodes[1],torso.nodes[2],.5);app.pointerMove(event(coord(edge)));assert.ok(op.selection.hover);edgePanelClick(edge);edgePanelClick(cubic(sleeve.nodes[0],sleeve.nodes[1],.5));assert.equal(op.selection.selected.length,2);assert.equal(op.selection.choice.key,area.key);assert.equal(op.phase,'READY_TO_CREATE');assert.ok(op.selection.choice.perimeter.some(f=>!f.selected));const before=clone(app.editorState().project.views.front);get('panel-preview').onclick({target:{closest:s=>s==='[data-create-edge-panel]'?{}:null}});assert.equal(selectedPath().semanticType,'region');for(const o of before)assert.deepEqual(app.editorState().project.views.front.find(x=>x.id===o.id),o);app.undo();assert.deepEqual(app.editorState().project.views.front,before);app.redo();assert.ok(app.editorState().project.views.front.some(o=>o.semanticType==='region'));});
test('Polygonize no preselection still discovers sleeve from individually open paths',()=>{const {p}=visualHoodie();app.open(p);const op=beginAreaViaModal();assert.equal(op.phase,'SELECT_AREA');assert.equal(op.selection.topology.candidates.length,1);assert.deepEqual(app.editorState().selected,[]);app.cancelPanelEdges();});
test('Polygonize actual area handlers disambiguate neighboring faces',()=>{const {p,body,a,b}=edgePanelDocument();app.open(p);const op=beginAreaViaModal();assert.equal(op.selection.candidates.length,2);app.pointerMove(event(coord({x:240,y:150})));assert.match(get('draft').innerHTML,/panel-edge-region/);chooseVisualArea({x:240,y:150});const key=op.selection.choice.key;chooseVisualArea({x:240,y:420});assert.notEqual(op.selection.choice.key,key);assert.equal(op.phase,'READY_TO_CREATE');app.cancelPanelEdges();});
test('Polygonize working set excludes graphic, image, text, effects, hidden/locked and Back linework',()=>{const {p,torso,sleeve}=visualHoodie();const names=['hidden','locked','graphic','effect'];const extra=names.map((name,i)=>{const o=makePath(name,`M450 ${400+i*10}L550 ${400+i*10}`,'none');o.category='construction';if(name==='hidden')o.hidden=true;if(name==='locked')o.locked=true;if(name==='graphic')o.category='graphic';if(name==='effect'){o.source=torso.id;o.construction={type:'stitch',offset:5};}return o;});p.views.front.push(...extra,{id:'panel-text',type:'text',name:'Decoración',text:'Logo',fontSize:20,w:100,h:40,matrix:[1,0,0,1,400,400]});const backLine=makePath('Espalda','M405 450L570 450','none');p.views.back=[backLine];app.open(p);const op=beginAreaViaModal(),ids=op.selection.topology.scopeIds;assert.deepEqual(ids.slice().sort(),[torso.id,sleeve.id].sort());assert.equal(op.selection.topology.candidates.length,1);assert.equal(app.editorState().project.views.front.find(o=>o.id===torso.id).modifiers[0].id,'hoodie-seam');app.cancelPanelEdges();});
test('Polygonize area Escape, tool switch and view switch preserve document and normal selection',()=>{const {p,torso,inside}=visualHoodie();app.open(p);app.selectTreeObject(torso.id,{});const before=clone(app.editorState().project);beginAreaViaModal();chooseVisualArea(inside);escapePanel();assert.equal(app.editorState().panelEdgeState,null);assert.deepEqual(app.editorState().selected,[torso.id]);assert.deepEqual(app.editorState().project,before);beginAreaViaModal();app.toolSet('pen');assert.equal(app.editorState().panelEdgeState,null);assert.deepEqual(app.editorState().project,before);app.toolSet('select');beginAreaViaModal();back.onclick();assert.equal(app.editorState().panelEdgeState,null);assert.deepEqual(app.editorState().project,before);front.onclick();});
test('Polygonize source edit updates or safely invalidates while preserving panel appearance',()=>{const {p,torso,inside}=visualHoodie();app.open(p);beginAreaViaModal();chooseVisualArea(inside);app.confirmEdgePanel();const r=selectedPath();app.applyColor('#bb4411');app.setFabric('denim');const before=clone(r.nodes),source=app.editorState().project.views.front.find(o=>o.id===torso.id);app.selectId(torso.id,false,true);app.setProperty('x',bounds(source).x+10);const updated=app.editorState().project.views.front.find(o=>o.id===r.id);assert.equal(updated.fill,'#bb4411');assert.equal(updated.fabricTexture.type,'denim');assert.ok(updated.panelEdgeInvalid||JSON.stringify(updated.nodes)!==JSON.stringify(before));});
test('Polygonize cached area preparation survives color change without rerunning topology',()=>{const {p,inside}=visualHoodie();app.open(p);const op=beginAreaViaModal(),topology=op.selection.topology,metrics=op.metrics;for(let i=0;i<100;i++)app.pointerMove(event(coord({x:inside.x+i*.01,y:inside.y})));assert.equal(op.selection.topology,topology);assert.equal(op.metrics,metrics);app.applyColor('#559966',[]);assert.equal(app.editorState().panelEdgeState.selection.topology,topology);app.cancelPanelEdges();});
test('Polygonize cached area selection invalidates on source geometry, visibility and lock changes',()=>{const {p,torso,inside}=visualHoodie();app.open(p);app.selectId(torso.id,false,true);beginAreaViaModal();chooseVisualArea(inside);const original=app.editorState().panelEdgeState.selection;app.setProperty('x',bounds(selectedPath()).x+1);assert.notEqual(app.editorState().panelEdgeState.selection,original);assert.equal(app.editorState().panelEdgeState.selection?.choice,null);app.cancelPanelEdges();});
for(const action of ['hideSelection','lockSelection'])test('Polygonize actual '+action+' invalidates prepared area',()=>{const {p,torso,inside}=visualHoodie();app.open(p);app.selectId(torso.id,false,true);beginAreaViaModal();chooseVisualArea(inside);app.action(action);const op=app.editorState().panelEdgeState;assert.equal(op.selection,null);assert.equal(op.phase,'ERROR');assert.equal(op.diagnostics[0].code,'NO_REGIONS');app.cancelPanelEdges();});
test('Polygonize centered Live Mirror keeps one logical panel pair and appearance',()=>{const {p,body,a}=edgePanelDocument();p.liveMirror=true;body.nodes=makePath('Base','M100 100L600 100L600 500L100 500Z','#fff').nodes;body.mirrorPolicy='centered';const cut=makePath('División','M100 240L200 240L200 100','none');p.views.front=[body,cut];app.open(p);app.action('selectPanelArea');chooseVisualArea({x:150,y:180});assert.ok(app.editorState().panelEdgeState.selection.choice);app.confirmEdgePanel();let regions=app.editorState().project.views.front.filter(o=>o.semanticType==='region');assert.equal(regions.length,2);const master=regions.find(o=>!o.instanceOf),peer=regions.find(o=>o.instanceOf);assert.equal(peer.instanceOf,master.id);app.applyColor('#229944');assert.equal(peer.fill,'#229944');app.setFabric('denim');assert.equal(peer.fabricTexture.type,'denim');});
test('Polygonize no closed owner still uses semantic parent Live Mirror according to existing rules',()=>{const {p,torso,inside}=visualHoodie();p.liveMirror=true;p.centerAxis=800;torso.mirrorPolicy='centered';app.open(p);beginAreaViaModal();chooseVisualArea(inside);app.confirmEdgePanel();const regions=app.editorState().project.views.front.filter(o=>o.semanticType==='region');assert.equal(regions.length,2);assert.equal(regions.filter(o=>o.instanceOf).length,1);const owner=app.editorState().project.views.front.find(o=>o.id===regions[0].panelOf);assert.equal(owner.ownerId,torso.id);assert.ok(owner.visualPanelOwner);});
test('Polygonize topology is scoped to selected garment neighborhood, excluding separate garment instance',()=>{const {p,inside}=visualHoodie(),other=makePath('Otra prenda','M1400 100L1500 100L1500 200L1400 200Z','#fff');other.category='structure';p.views.front.push(other);app.open(p);app.selectTreeObject(p.views.front[0].id,{});const op=beginAreaViaModal();assert.ok(!op.selection.topology.scopeIds.includes(other.id));chooseVisualArea(inside);assert.ok(op.selection.choice);app.cancelPanelEdges();});
